/**
 * Method applies passed export rule for passed property and path.
 *
 * @param rule - sync rule to apply
 * @param path - path in manifest which shold be updated by export
 * @param key - property name/key
 * @param application - V4 application (app.json config file)
 * @param manifest - Manifest of the given app
 * @param appSchema - App schema
 */
const applyExportRule = (
    rule: SyncRule,
    path: string,
    key: string,
    application: ApplicationV4,
    manifest: object,
    appSchema: Definition
) => {
    let manifestSection = getManifestSectionByPathV4(manifest, path, undefined, undefined, true);
    let existing = true;
    if (manifestSection === undefined) {
        existing = false;
        manifestSection = prepareValueForPath();
    }

    const exportParams: ExportToManifestParams = {
        syncRule: rule,
        manifestSection,
        configObject: application,
        configPropertyKey: key,
        manifestKey: key,
        syncRuleKey: key
    };
    const propertyDefinition = (appSchema.definitions.AppSettings as Definition).properties[key];
    transferPropertyToManifest(exportParams, propertyDefinition as Definition, {});
    if (!existing && Object.keys(manifestSection).length) {
        // Apply virtual object to existing manifest
        setManifestSectionByPathV4(manifest, path, manifestSection);
    }
};

/**
 * API for the export of a V4 app configuration.
 * Export means the transfer of the properties and values of the given config to manifest entries or flex changes.
 *
 * @param application - V4 application (app.json config file)
 * @param manifest - Manifest of the given app
 * @param appSchema - App schema
 * @returns ExportResults = object comprising the updated manifest and a list of flex changes
 */
const exportApplicationV4 = (application: ApplicationV4, manifest: Manifest, appSchema: Definition): ExportResults => {
    const exportResults: ExportResults = prepareDefaultExportResult(manifest);
    const applicationV4 = Object.assign(new ApplicationV4(), application);

    //transform application settings
    applicationV4.settings = Object.assign(new AppSettings(), applicationV4.settings);
    for (const key in (appSchema.definitions.AppSettings as Definition).properties) {
        const syncRule = getReflectMetadata(applicationV4.settings, key);
        if (syncRule && syncRule.manifest) {
            const path = syncRule.manifest.path();
            if (syncRule.manifest.export) {
                applyExportRule(syncRule, path, key, application, exportResults.manifest, appSchema);
            } else {
                // Read section/segment with 'readOnly=true'
                let manifestSection = getManifestSectionByPathV4(
                    exportResults.manifest,
                    path,
                    undefined,
                    undefined,
                    true
                );
                const settingProperty = application.settings?.[key];
                // Property could be empty object or undefined, check for both
                if (
                    settingProperty !== undefined &&
                    (typeof settingProperty !== 'object' || Object.keys(settingProperty).length !== 0)
                ) {
                    // Read section/segment with 'readOnly=false'(create object/array if existing value not found by given path)
                    manifestSection =
                        manifestSection ??
                        getManifestSectionByPathV4(exportResults.manifest, path, undefined, undefined, false);
                    manifestSection[key] = application.settings[key];
                } else if (manifestSection && key in manifestSection) {
                    delete manifestSection[key];
                    deleteEmptyStructure(exportResults.manifest, path, false);
                }
            }
        }
    }
    //transform routing
    exportResults.manifest[ManifestSection.ui5].routing = transformRoutingV4(
        application['home'],
        application['pages'],
        exportResults.manifest
    ) as SapUi5Routing;

    // Update FCL data
    updateFcl(exportResults.manifest[ManifestSection.ui5] as v4.SapUi5V4, application);

    return exportResults;
};

/**
 * General API for the export of a V4 config page.
 * Export means the transfer of the properties and values of the given config to manifest entries or flex changes.
 *
 * @param exportParametersV4 - list of parameters for the export; the list varies for the different schema types
 * @param ui5Version - the minUi5Version of the app
 * @returns ExportResults = object comprising the updated manifest and a list of flex changes
 */
export const exportPageV4 = (
    exportParametersV4: ExportParametersV4[FioriElementsVersion.v4],
    ui5Version: UI5Version
): ExportResults | undefined => {
    if (exportParametersV4[SchemaType.ListReport]) {
        return exportListReportPage(
            exportParametersV4[SchemaType.ListReport],
            ui5Version,
            TemplateType.ListReportObjectPageV4
        );
    } else if (exportParametersV4[SchemaType.ObjectPage]) {
        return exportObjectPage(exportParametersV4[SchemaType.ObjectPage], ui5Version);
    } else if (exportParametersV4[SchemaType.Application]) {
        const { application, manifest, jsonSchema } = exportParametersV4[SchemaType.Application];
        return exportApplicationV4(application, manifest, jsonSchema);
    } else if (exportParametersV4[SchemaType.AnalyticalListPage]) {
        return exportAnalyticalListPage(exportParametersV4[SchemaType.AnalyticalListPage], ui5Version);
    } else if (exportParametersV4[SchemaType.FPMCustomPage]) {
        return exportFPMCustomPageConfig(exportParametersV4[SchemaType.FPMCustomPage], defaultExportResult);
    }
};

/**
 * Run through the given CustomPage config and return respective export result.
 *
 * @param exportParameters - all API parameters needed for the export
 * @returns Export result.
 */
const exportCustomPage = (exportParameters: ExportFPMCustomPageV4Parameters): ExportResults => {
    const { jsonSchema, views, page, manifest, logger } = exportParameters;
    const exportResults: ExportResults = prepareDefaultExportResult(exportParameters.manifest);
    let viewData: ExtensionFileData | undefined = undefined;
    if (jsonSchema && Object.keys(jsonSchema).length > 0) {
        viewData = getPageCustomViewFile(views || [], page.name, manifest, exportParameters.logger);
    }
    if (viewData) {
        getExtensionExportResult(viewData, exportResults, page.config, jsonSchema, 'view', logger);
    }

    return exportResults;
};

/**
 * Exports the config change of a single entity of the config, as indicated by an entityPath.
 * Export means the transfer of the properties and values of the given config to manifest entries or flex changes.
 *
 * @param exportParametersV4 - list of parameters for the export; the list varies for the different schema types
 * @param ui5Version - the minUi5Version of the app
 * @param deletionRequest - if set to true, any manifest setting specified by entityPath gets deleted even if it comprises any unknown property
 * @returns ExportResults = object comprising the updated manifest and a list of flex changes
 */
export const exportConfigEntityByPathV4 = (
    exportParametersV4: ExportV4WithPath[FioriElementsVersion.v4],
    ui5Version?: UI5Version,
    deletionRequest = false
): ExportResults | undefined => {
    if (exportParametersV4[SchemaType.ListReport]) {
        return exportListReportPage(
            exportParametersV4[SchemaType.ListReport],
            ui5Version,
            TemplateType.ListReportObjectPageV4,
            deletionRequest
        );
    } else if (exportParametersV4[SchemaType.ObjectPage]) {
        return exportObjectPage(exportParametersV4[SchemaType.ObjectPage], ui5Version, deletionRequest);
    } else if (exportParametersV4[SchemaType.AnalyticalListPage]) {
        return exportAnalyticalListPage(exportParametersV4[SchemaType.AnalyticalListPage], ui5Version, deletionRequest);
    } else if (exportParametersV4[SchemaType.FPMCustomPage]) {
        return exportCustomPage(exportParametersV4[SchemaType.FPMCustomPage]);
    }
};
