import { js2xml, type Element } from 'xml-js';
import type {
    ExportFPMCustomPageV4Parameters,
    ExportResults,
    ExtensionLogger,
    SchemaDefinition
} from '@sap/ux-specification-types';
import { ChangeIndicator, MacrosPropertyType } from '@sap/ux-specification-types';
import { getManifestPage, getPageCustomExtensionFile, getPageCustomViewFile } from '../utils/utils';
import { getCustomExtensionFragmentDefinitionKey, getRootElement, parseXML, traverseSchema } from '../utils/macros';
import type { TraverseData } from '../utils/macros';
import type { ExtensionFileData } from '../types';
import type { TransferParameterTypeV4 } from './types';

/**
 * Tracks deletion operations during export traversal.
 */
export interface ExportTraverseSchemaData {
    nodesToDelete?: Array<{
        element: Element;
        parent: Element;
    }>;
}

/**
 * Method compares values if values are different after converted to string.
 * It is used to determine if we need make change in XML file.
 *
 * @param {unknown} value1 First value to compare.
 * @param {unknown} value2 Second value to compare.
 * @returns {boolean} Returns true if values are same after values converted to string.
 */
function isExportValueEquals(value1: unknown, value2: unknown): boolean {
    return value1 !== undefined && value2 !== undefined ? `${value1}` === `${value2}` : value1 === value2;
}

/**
 * Method deletes property by emoving attribute from element.
 * Method also considers if it is last attribute and element is complex property, then element would removed as well.
 *
 * @param {TraverseData} traverseData Schema and XML traverse data.
 * @param {string} name Name of property.
 */
function deleteProperty(traverseData: TraverseData<ExportTraverseSchemaData>, name: string): void {
    const { element, schema, parent, contextPath } = traverseData;
    delete element.attributes[name];

    if (
        schema.metadata?.type === MacrosPropertyType.Property &&
        Object.keys(element.attributes).length === 0 &&
        parent?.element.elements
    ) {
        // Last attribute is deleted for property - if element is property then remove property itself
        const context = contextPath[contextPath.length - 1];
        if (context) {
            parent.element.elements.splice(context.index, 1);
        }
    }
}

/**
 * Callback method of traversing schema and XML.
 * Method exports value from page config object to XML element.
 *
 * @param {TraverseData} traverseData Schema and XML traverse data.
 * @param {SchemaDefinition} property Schema property to use for export.
 * @param {object} config Fragment of page config object.
 * @param {string} name Name of property to export.
 * @returns {boolean} Is new value differs.
 */
function detectElementDeletion(
    traverseData: TraverseData<ExportTraverseSchemaData>,
    property: SchemaDefinition,
    config: object | undefined,
    name: string
): boolean {
    const { element, parentElement } = traverseData;
    if (element?.name === name) {
        if (traverseData.data?.nodesToDelete) {
            traverseData.data.nodesToDelete.push({
                element,
                parent: parentElement
            });
        }
        return true;
    }
    return false;
}

/**
 * Callback method of traversing schema and XML.
 * Method exports value from page config object to XML element.
 *
 * @param {TraverseData} traverseData Schema and XML traverse data.
 * @param {SchemaDefinition} property Schema property to use for export.
 * @param {object} config Fragment of page config object.
 * @param {string} name Name of property to export.
 * @returns {boolean} Is new value differs.
 */
function exportProperty(
    traverseData: TraverseData<ExportTraverseSchemaData>,
    property: SchemaDefinition,
    config: object,
    name: string
): boolean {
    const { contextPath, fullSchema, element } = traverseData;
    let differs = false;
    if (property.hidden) {
        // Currently we ignore hidden properties
        return false;
    }
    if (name in config && config[name] !== undefined) {
        if (property.isViewNode) {
            if (!element.elements) {
                element.elements = [];
            }
            const targetElement = {
                name,
                type: 'element'
            };
            element.elements.push(targetElement);
            return traverseSchema<ExportTraverseSchemaData>(
                {
                    fullSchema: fullSchema,
                    schema: property,
                    element: targetElement,
                    contextPath: [
                        ...contextPath,
                        {
                            name,
                            index: 0
                        }
                    ],
                    config: config[name],
                    parent: traverseData,
                    parentElement: element,
                    data: traverseData.data
                },
                exportProperty,
                detectElementDeletion
            );
        } else if (element && !isExportValueEquals(element.attributes?.[name], config[name])) {
            const isObject = typeof config[name] === 'object' && config[name] !== null && !Array.isArray(config[name]);

            if (isObject) {
                // If the config value is an object, treat it as a child element with properties as attributes
                element.elements = element.elements || [];
                element.elements.push({
                    name,
                    type: 'element',
                    attributes: config[name]
                });
            } else {
                element.attributes = element.attributes || {};
                element.attributes[name] = config[name];
            }
            differs = true;
        }
    } else if (element?.attributes?.[name]) {
        deleteProperty(traverseData, name);
        differs = true;
    }
    return differs;
}

/**
 * Deletes elements from their parent containers.
 *
 * @param nodesToDelete Array of elements marked for deletion with their parent references
 */
function deleteElements(nodesToDelete: ExportTraverseSchemaData['nodesToDelete']): void {
    for (const deleteNode of nodesToDelete) {
        const { parent, element } = deleteNode;

        if (!parent?.elements) {
            continue;
        }

        const index = parent.elements.findIndex((el) => el === element);
        if (index !== -1) {
            parent.elements.splice(index, 1);
        }
    }
}

/**
 * Populates export results with data from extension.
 *
 * @param {ExtensionFileData} extensionData Extension data from parsed XML file.
 * @param {ExportResults} exportResults Export results API parameters needed for the export.
 * @param {object} config Extension of page config object.
 * @param {SchemaDefinition} jsonSchema Extesion definition schema.
 * @param {string} extensionType Extension type - view or fragment.
 * @param {ExtensionLogger | undefined} logger Logger class for logging messages.
 */
export function getExtensionExportResult(
    extensionData: ExtensionFileData,
    exportResults: ExportResults,
    config: object,
    jsonSchema: SchemaDefinition,
    extensionType: 'view' | 'fragment',
    logger?: ExtensionLogger
) {
    const element = parseXML(extensionData.file, false, logger);
    if (element) {
        const coreElement = getRootElement(element);
        const traversionData: ExportTraverseSchemaData = {
            nodesToDelete: []
        };
        const differs = traverseSchema<ExportTraverseSchemaData>(
            {
                fullSchema: jsonSchema,
                schema: jsonSchema,
                element: coreElement,
                contextPath: [],
                config,
                data: traversionData
            },
            exportProperty,
            detectElementDeletion
        );
        if (differs) {
            if (traversionData.nodesToDelete?.length) {
                deleteElements(traversionData.nodesToDelete);
            }
            const fileContent = js2xml(element, { spaces: 4 });
            const extensionExportResult = {
                dataSourceUri: extensionData.file.dataSourceUri,
                fileContent,
                changeIndicator: ChangeIndicator.Updated
            };
            if (extensionType === 'view') {
                exportResults.views = [extensionExportResult];
            } else if (extensionType === 'fragment') {
                exportResults.fragments.push(extensionExportResult);
            }
        }
    }
}

/**
 * Run through the given FPM Custom Page config and return respective XML View result.
 * If no changes in config, then view is not returned.
 *
 * @param exportParameters All API parameters needed for the export.
 * @param defaultExportResult Default export result.
 * @returns Object comprising the updated xml view
 */
export const exportFPMCustomPageConfig = (
    exportParameters: ExportFPMCustomPageV4Parameters,
    defaultExportResult: ExportResults
): ExportResults => {
    const { views, manifest, jsonSchema, page, logger } = exportParameters;
    const exportResults: ExportResults = { ...defaultExportResult, manifest };
    let viewData: ExtensionFileData | undefined = undefined;
    if (jsonSchema && Object.keys(jsonSchema).length > 0) {
        viewData = getPageCustomViewFile(views || [], page.name, manifest, logger);
    }
    if (viewData) {
        getExtensionExportResult(viewData, exportResults, page.config, jsonSchema, 'view', logger);
    }

    return exportResults;
};

/**
 * Runs through the given config and pushes changed fragments into export results.
 *
 * @param {TransferParameterTypeV4} transferParameters List of transfer parameters passed from API.
 * @param {string} fragmentName Full name of the fragment.
 * @param {object} config Current (sub)object of the configuration file.
 */
export const exportXMLFragmentConfig = (
    transferParameters: TransferParameterTypeV4,
    fragmentName: string,
    config: object
): void => {
    const { appSchema, exportResults, fragments, pageNameArray, logger } = transferParameters;
    const { manifest } = exportResults;
    let fragmentData: ExtensionFileData | undefined = undefined;
    const extensionType = 'fragment';
    if (appSchema && Object.keys(appSchema).length > 0) {
        const targetManifestPage = getManifestPage(manifest, pageNameArray[0]);
        fragmentData = getPageCustomExtensionFile(fragments, targetManifestPage, manifest, extensionType, fragmentName);
    }
    if (fragmentData) {
        const definitionKey = getCustomExtensionFragmentDefinitionKey(fragmentName);
        const targetConfigSchema = appSchema['definitions'][definitionKey] as SchemaDefinition;
        const tempSchema = {
            ...targetConfigSchema,
            definitions: appSchema['definitions']
        } as SchemaDefinition;
        getExtensionExportResult(fragmentData, exportResults, config, tempSchema, extensionType, logger);
    }
};
