export class QuickVariantSelectionV4OP implements v4.QuickVariantSelectionV4 {
    @syncRule({
        manifest: {
            path: (pageName: string[], manifest: Manifest, sectionId: string): string =>
                getTableSettingsPathForOP(pageName, manifest, sectionId) + QUICKVARPATH
        }
    })
    paths: v4.AnnotationPathAsObject[];

    @syncRule({
        manifest: {
            path: (pageName: string[], manifest: Manifest, sectionId: string): string =>
                getTableSettingsPathForOP(pageName, manifest, sectionId) + QUICKVARPATH
        }
    })
    hideTableTitle?: boolean;

    @syncRule({
        manifest: {
            path: (pageName: string[], manifest: Manifest, sectionId: string): string =>
                getTableSettingsPathForOP(pageName, manifest, sectionId) + QUICKVARPATH
        }
    })
    showCounts?: boolean;
}

export class ObjectPageTable implements v4.ObjectPageTable {
    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    type?: v4.TableTypeV4;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP,
            export: exportPersonalization
        }
    })
    @validity({
        since: '1.86.0'
    })
    personalization?: PersonalizationTypeOP | boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    selectionMode?: v4.SelectionMode;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    selectAll?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    selectionLimit?: number;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    @descriptionSrcURL('https://ui5.sap.com/sdk/#/topic/4bab6f2043814257974b52d4dafe1dcd')
    enableExport?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    quickVariantSelection?: QuickVariantSelectionV4OP;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    @descriptionSrcURL('https://ui5.sap.com/sdk/#/topic/f3cc057e405c4fd58ee2ed42c557797c')
    condensedTableLayout?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.86.0'
    })
    enableFullScreen?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.84.0'
    })
    enablePaste?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.117.0'
    })
    @descriptionSrcURL('https://ui5.sap.com/#/topic/7f844f1021cd4791b8f7408eac7c1cec')
    hierarchyQualifier?: string;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.120.0'
    })
    @descriptionSrcURL('https://ui5.sap.com/#/topic/c0f6592a592e47f9bb6d09900de47412')
    widthIncludingColumnHeader?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP
        }
    })
    @validity({
        since: '1.123.0'
    })
    @descriptionSrcURL('https://ui5.sap.com/#/topic/c0f6592a592e47f9bb6d09900de47412')
    disableCopyToClipboard?: boolean;

    @syncRule({
        manifest: {
            path: getTableSettingsPathForOP,
            import: importEnableMassEdit,
            export: exportEnableMassEdit
        }
    })
    @validity({
        since: '1.126.0'
    })
    enableMassEdit?: v4.EnableMassEdit;
}

