import { DefinitionName, type Manifest, type v4 } from '@sap/ux-specification-types';
import { description, isViewNode, syncRule, validity } from '../../../common/decoration/decorators';
import { addPatternForBindingChangeOfEnumLR } from '../../../common/decoration/control';
import { getHeaderActionsPath } from '../../application';
import { Decorator } from '../../sync-rules/DecoratorClass';
import { addEnumForActionAnchor, addHeaderFooterCustomActionDefinition } from '../../utils';

/**
 * Sync class for Position
 */
export class CustomHeaderActionPosition implements v4.CustomHeaderActionPosition {
    @syncRule({
        manifest: {
            path: (pageName: string[], manifest: Manifest, sectionId: string, columnKey: string): string =>
                getHeaderActionsPath(pageName, manifest, sectionId, columnKey) + '/position'
        }
    })
    @validity({
        since: '1.84.0'
    })
    anchor?: string;
    @syncRule({
        manifest: {
            path: (pageName: string[], manifest: Manifest, sectionId: string, columnKey: string): string =>
                getHeaderActionsPath(pageName, manifest, sectionId, columnKey) + '/position'
        }
    })
    @validity({
        since: '1.84.0'
    })
    placement: v4.ActionPlacement;
}

@isViewNode
@description('Custom Action')
export class CustomHeaderAction extends Decorator implements v4.CustomHeaderAction {
    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        }
    })
    @validity({
        since: '1.84.0'
    })
    text: string;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        }
    })
    @validity({
        since: '1.84.0'
    })
    position: CustomHeaderActionPosition;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        }
    })
    @validity({
        since: '1.84.0'
    })
    press: string;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        },
        generate: addPatternForBindingChangeOfEnumLR
    })
    @validity({
        since: '1.84.0'
    })
    visible?: boolean;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        },
        generate: addPatternForBindingChangeOfEnumLR
    })
    @validity({
        since: '1.84.0'
    })
    enabled?: boolean;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        }
    })
    @validity({
        since: '1.142.0'
    })
    overflowGroup?: number;

    @syncRule({
        manifest: {
            path: getHeaderActionsPath
        }
    })
    @validity({
        since: '1.139.0'
    })
    priority?: v4.ActionPriority;

    init() {
        super.init();
        addHeaderFooterCustomActionDefinition(
            this.appSchema.get(),
            this.page.target,
            this.logger,
            this.getClassName() as DefinitionName,
            DefinitionName.HeaderActions
        );
        addEnumForActionAnchor(
            this.appSchema.get(),
            DefinitionName.HeaderActions,
            DefinitionName.CustomHeaderActionPosition
        );
    }
}
