export const getGroupedActionsPathForLR = (
    pageName: string[],
    manifest: Manifest,
    targetAnnotationEncoded: string,
    columnKey: string,
    targetAnnotation: string,
    configObject: object,
    originalIds: string[]
): string => {
    // views
    if (originalIds && ['overflowGroup', 'priority'].includes(originalIds[originalIds.length - 1])) {
        columnKey = originalIds[originalIds.length - 2];
    }
    if (targetAnnotation) {
        const annotationEncoded = targetAnnotation?.replace(/\//gi, '??');
        return getControlConfigurationPath(pageName) + `/${annotationEncoded}/actions/${columnKey}`;
    }
    // no views
    return getControlConfigurationPath(pageName) + `/@${UIAnnotationTerms.LineItem}/actions/${columnKey}`;
};

export const getGroupedActionsPathForOP = (
    pageName: string[],
    manifest: Manifest,
    sectionId: string,
    columnKey: string,
    sectionIdEncoded: string,
    configObject: object,
    originalIds: string[]
): string => {
    if (originalIds && ['overflowGroup', 'priority'].includes(originalIds[originalIds.length - 1])) {
        columnKey = originalIds[originalIds.length - 2];
    }
    const columnKeyEncoded = columnKey.replace(/\//gi, '??');
    if (sectionId) {
        const sectiondIdEncoded = sectionId.replace(/\//gi, '??');
        return getControlConfigurationPath(pageName) + `/${sectiondIdEncoded}/actions/${columnKeyEncoded}`;
    } else {
        // header action group
        return getSettingsPathForHeaderOP(pageName) + `/actions/${columnKeyEncoded}`;
    }
};

