export const getCustomSectionPath = (
    pageName: string[],
    _manifest: Manifest,
    sectionId: string,
    pathPart?: string
): string => {
    let path = getSettingsPathForPage(pageName) + `/content/body/sections/${sectionId}`;
    if (pathPart) {
        path += '/' + pathPart;
    }
    return path;
};

export const getCustomSectionActionPath = (
    pageName: string[],
    _manifest: Manifest,
    sectionId: string,
    actionId: string
): string => {
    return getSettingsPathForPage(pageName) + `/content/body/sections/${sectionId}/actions/${actionId}`;
};

export const getObjectPageCustomHeaderSectionPath = (
    pageName: string[],
    _manifest: Manifest,
    sectionId: string,
    pathPart?: string
): string => {
    let path = getSettingsPathForPage(pageName) + `/content/header/facets/${sectionId}`;
    if (pathPart) {
        path += '/' + pathPart;
    }
    return path;
};

export const getCustomSubSectionPath = (
    pageName: string[],
    manifest: Manifest,
    sectionId: string,
    pathPart?: string,
    targetAnnotation?: string,
    configObject?: object,
    originalIds?: string[]
): string => {
    let parent = sectionId;

    if (originalIds) {
        if (originalIds[0] === 'sections' && originalIds[1]) {
            parent = originalIds[1];
        }
        if (originalIds[2] === 'subsections' && originalIds[3]) {
            pathPart = `subSections/${originalIds[3]}`;
        }
    }
    let path = getSettingsPathForPage(pageName) + `/content/body/sections/${parent}`;
    if (pathPart) {
        path += '/' + pathPart;
    }
    return path;
};

