export class ApplicationV4 implements Application {
    $schema?: string;
    id?: string;
    pages?: v4.Pages;
    home?: string;
    target?: Target;
    @childId('settings')
    settings?: AppSettings;
}

export class AppSettings implements v4.AppSettings {
    @syncRule({
        manifest: {
            path: (): string => 'sap.app'
        }
    })
    title?: string;

    @syncRule({
        manifest: {
            path: (): string => 'sap.app'
        }
    })
    description?: string;

    @syncRule({
        manifest: {
            path: (): string => 'sap.fiori'
        }
    })
    cloudDevAdaptationStatus?: CloudDevAdaptationStatus;

    @syncRule({
        manifest: {
            path: (): string => 'sap.ui5/routing/config'
        }
    })
    @validity({
        since: '1.78.0'
    })
    flexibleColumnLayout?: v4.FlexibleColumnLayoutV4;

    @syncRule({
        manifest: {
            path: (): string => 'sap.ui5'
        }
    })
    @validity({
        since: '1.56.0'
    })
    flexEnabled?: boolean;

    @syncRule({
        manifest: {
            path: (): string => 'sap.ui5'
        }
    })
    dependencies?: Dependencies;

    @syncRule({
        manifest: {
            path: (): string => 'sap.fe/app',
            export: (manifestSection, configObject, key): void => {
                if (typeof manifestSection !== 'object') {
                    return;
                }
                const setting = configObject?.['settings']?.[key];
                if (setting && Object.keys(setting).length !== 0) {
                    manifestSection[key] = setting;
                } else if (key in manifestSection) {
                    delete manifestSection[key];
                }
            }
        }
    })
    @validity({
        since: '1.134.0'
    })
    hideDraft?: v4.HideDraft;

    @syncRule({
        manifest: {
            path: (): string => 'sap.fe/macros/table',
            export: (manifestSection, configObject, key): void => {
                if (typeof manifestSection !== 'object') {
                    return;
                }
                const setting = configObject?.['settings']?.[key];
                if (setting && Object.keys(setting).length !== 0) {
                    manifestSection[key] = setting;
                } else if (key in manifestSection) {
                    delete manifestSection[key];
                }
            }
        }
    })
    @validity({
        since: '1.136.5'
    })
    defaultCreationMode?: TableCreationModeType.InlineCreationRows | EmptyOption;

    @syncRule({
        manifest: {
            path: (): string => 'sap.ui5/routing/config'
        }
    })
    viewType?: ViewTypes;

    @syncRule({
        manifest: {
            path: (): string => 'sap.ui5/routing/config'
        }
    })
    path?: string;

    @syncRule(controllerExtensions)
    controllerExtensions?: v4.ControllerExtensions;

    @syncRule({
        manifest: {
            path: (): string => 'sap.fe/macros/table',
            export: (manifestSection, configObject, key): void => {
                if (typeof manifestSection !== 'object') {
                    return;
                }
                const setting = configObject?.['settings']?.[key];
                if (setting && Object.keys(setting).length !== 0) {
                    manifestSection[key] = setting;
                } else if (key in manifestSection) {
                    delete manifestSection[key];
                }
            }
        }
    })
    @validity({
        since: '1.139.0'
    })
    defaultPopinLayout?: PopinLayout;

    @syncRule({
        manifest: {
            path: (): string => 'sap.fe/app'
        }
    })
    @validity({
        since: '1.144.0'
    })
    enableLazyLoading?: boolean;
}
