/**
 * @file This file contains the types used for modelling tables on any v2 page.
 */

import type { smarttable } from 'sap/ui/comp/library';

export enum TableTypeV2Enum {
    ResponsiveTable = 'ResponsiveTable',
    GridTable = 'GridTable',
    AnalyticalTable = 'AnalyticalTable',
    TreeTable = 'TreeTable'
}

// Start: Interfaces used for the multi-view multi-table scenario (quickVariantSelectionX).

/**
 * @isViewNode false
 */
export interface MultiViewsVariants {
    [key: string]: Table;
}

/**
 * Views
 *
 * @isViewNode true
 */
export interface MultiViewsDefinition {
    /**
     * Use this property to ensure that data are automatically loaded when the page is opened.
     */
    enableAutoBinding?: boolean;
    /**
     * You can show the counts of entries of each view. To do so, add the showCounts option and set it to true.
     */
    showCounts?: boolean;
    /**
     * List of views
     */
    variants: MultiViewsVariants;
}

// End: Interfaces used for the multi-view multi-table scenario (quickVariantSelectionX).

// Start: Interfaces used for the multi-view single-table scenario (quickVariantSelection).

export interface ViewOnTable {
    /**
     * The key property is mandatory. It is used for initializing the corresponding SegmentedButton item.
     */
    key: string;
    /**
     * Use annotationPath to define a specific variant that points to a SelectionVariant or SelectionPresentationVariant annotation.
     */
    annotationPath: string;
}

export interface MultiViewsOnTable {
    /**
     * To show the number of available records, set showCounts to true.
     */
    showCounts?: boolean;
    /**
     * The variants section contains a set of entries that point to a SelectionVariant or SelectionPresentationVariant annotation.
     */
    variants: {
        [key: string]: ViewOnTable;
    };
}

// End: Interfaces used for the multi-view single-table scenario (quickVariantSelection).

/**
 * Table
 *
 * @isViewNode true
 */
export interface Table {
    /**
     * This property can be used to indicate that a table or chart should be based on a different entity set than the main entity set
     */
    entitySet?: string;
    /**
     * Specify a SelectionVariant or SelectionPresentationVariant annotation for the entity set to configure the table or chart
     */
    annotationPath?: string;
    /**
     * To enable navigation for charts, you have to set the property to "true" and maintain an internal navigation target in the manifest.
     */
    showItemNavigationOnChart?: boolean;

    views?: MultiViewsDefinition;

    /**
     * With quickVariantSelection, you can switch to multiple views (single table mode).
     * Each view links to a variant you have added to your annotations.
     */
    quickVariantSelection?: MultiViewsOnTable;

    /**
     * The showTablePersonalisation attribute can be set to false to hide the table personalization button.
     */
    showTablePersonalisation?: boolean;
    /**
     * Specifies the type of export to be used in the SmartTable control.
     */
    exportType?: smarttable.ExportType;
    /**
     * useExportToExcel must be set to true if you want to export data to a spreadsheet application, for example Microsoft Excel.
     */
    useExportToExcel?: boolean;
}
