export class ActionAfterExecutionConfigurationToolBarLR implements v4.ActionAfterExecutionConfiguration {
    @syncRule({
        manifest: {
            path: (
                pageName: string[],
                manifest: Manifest,
                sectionId: string,
                columnKey: string,
                targetAnnotation: string
            ): string =>
                getActionsPathForLR(pageName, manifest, sectionId, columnKey, targetAnnotation) + '/afterExecution'
        }
    })
    @descriptionSrcURL('https://ui5.sap.com/#/topic/2c65f07f44094012a511d6bd83f50f2d')
    navigateToInstance?: boolean;
    @syncRule({
        manifest: {
            path: (
                pageName: string[],
                manifest: Manifest,
                sectionId: string,
                columnKey: string,
                targetAnnotation: string
            ): string =>
                getActionsPathForLR(pageName, manifest, sectionId, columnKey, targetAnnotation) + '/afterExecution'
        }
    })
    enableAutoScroll?: boolean;
}

