/**
 * Add general settings to schema (LR or ALP).
 *
 * - Adds Selection-(PresentationVariant) related enums to the schema.
 */
export class GeneralListReportSettings extends BaseConstruct {
    /**
     * Constructor for general settings of ListReport.
     *
     * @param settings - general settings (App, Page, AppSchema, Logger)
     */
    constructor(settings: GeneralSettings) {
        super(settings);
    }

    init() {
        this.addSPVEnums(DefinitionName.AnnotationPathAsObject);
    }

    /**
     * Adds Selection-(PresentationVariant) related enums to the schema.
     *
     * @param definitionName - definition name
     */
    private addSPVEnums(definitionName: DefinitionName) {
        const targetTerms = [UIAnnotationTerms.SelectionVariant, UIAnnotationTerms.SelectionPresentationVariant];
        const uiAnnotations = this.page.getUIAnnotations();
        if (!uiAnnotations) {
            return;
        }
        const enumStrings = Object.values(uiAnnotations)
            .filter((annotation) => targetTerms.includes(annotation.term as UIAnnotationTerms))
            .map((annotation) =>
                annotation.qualifier ? `${annotation.term}#${annotation.qualifier}` : annotation.term
            );
        const enums = [...new Set(enumStrings)];
        this.appSchema.addEnumToSchema(definitionName, ['properties', SchemaTag.annotationPath], enums);
    }
}

/**
 * Add filter bar to schema (LR or ALP).
 */
export class FilterBar extends BaseConstruct {
    /**
     *
     * @param settings - general settings (App, Page, AppSchema, Logger)
     */
    constructor(settings: GeneralSettings) {
        super(settings);
    }

    /**
     * Initializes the filter bar adjustments.
     */
    init() {
        this.addFilterBar(
            this.page.getEntityType(),
            this.appSchema,
            this.page.target,
            this.page.getUIVocabularyAlias()
        );
    }

    // Implementation for FilterBar can be added here

    private addVisualFilters() {
        getVisualFilters(this.page.target);
    }
    private addSelectionFields() {}

    /**
     * Adds filter bar to schema (LR or ALP).
     *
     * @param entityType - the entity type
     * @param schema - the application schema
     * @param v4Page - the actual page in the manifest
     * @param alias - alias definition for the UI vocabulary
     */
    private addFilterBar(entityType: EntityType, schema: AppSchema, v4Page: v4.SapUiAppPageV4, alias: string) {
        const selectionFields = alias && entityType?.annotations?.[alias]?.SelectionFields;
        let selectionFieldsDefinition;
        // Hide visualFilters/selectionFields depending on existing visual filters
        const appSchema = schema.get();
        const visualFilters = getVisualFilters(v4Page);
        if (visualFilters) {
            appSchema.definitions[DefinitionName.SelectionFields][SchemaTag.hidden] = true;
            appSchema.definitions[DefinitionName.SelectionFields]['properties'] = {};
            selectionFieldsDefinition = appSchema.definitions[DefinitionName.CompactFilters];
            selectionFieldsDefinition.additionalProperties = false;
            selectionFieldsDefinition.properties = {};
            addVisualFilters(entityType, appSchema, visualFilters, selectionFields);
        } else {
            const filterBar = schema.getDefinition(DefinitionName.FilterBar);
            filterBar.properties['initialLayout'][SchemaTag.hidden] = true;
            filterBar.properties['layout'][SchemaTag.hidden] = true;
            appSchema.definitions[DefinitionName.CompactFilters][SchemaTag.hidden] = true;
            appSchema.definitions[DefinitionName.VisualFilters][SchemaTag.hidden] = true;
        }
        selectionFieldsDefinition = addSelectionFields(
            entityType,
            appSchema,
            selectionFields,
            selectionFieldsDefinition
        );
        // Apply custom filter fields
        applyCustomFilterFields(appSchema, selectionFieldsDefinition, v4Page);
        // Add "manifestPath" to filter fields
        addManifestPathsToDefinitionPropertiesLR(
            schema.get(),
            v4Page.id,
            DefinitionName.SelectionFields,
            this.app.getManifest()
        );
    }
}

/**
 * Adjusts the entity type if a different entity set is maintained for a view.
 *
 * @param {EntitySet} entitySet - actual entity set (AVT information)
 * @param view - the current view in manifest
 * @param page - the page object
 * @param app - the app object
 * @returns the target entity type
 */
function getTargetEntityType(entitySet: EntitySet, view: object, page: Page, app: App): EntityType {
    let targetEntityType = page.getEntityType();
    let viewEntitySet = entitySet;
    if (view['entitySet'] && view['entitySet'] !== entitySet.name) {
        viewEntitySet = app.getAVT()?.entitySets.find((es) => {
            return es.name === view['entitySet'];
        });
        targetEntityType = viewEntitySet.entityType;
    }
    return targetEntityType;
}

/**
 * Adapts the table definition in schema.
 * Evaluates the path depending on if defaultTemplateAnnotationPath or Selection-/PresentationVariant is present.
 *
 * @param settings - general settings (App, Page, AppSchema, Logger)
 * @param templateAnnotation - defaultTemplateAnnotationPath as registered in manifest
 * @param tableDefinitionName - The name of the table definition in the schema
 */
function adaptTableDefinition(
    settings: GeneralSettings,
    templateAnnotation: string,
    tableDefinitionName: DefinitionName.Table | DefinitionName.ALPTableView
) {
    const { appSchema, page, app } = settings;
    let schemaIdForColumns = `${DefinitionName.LineItems}`;
    let schemaIdForActions;

    //here: tableDefinitionName = DefinitionName.Table
    const tableDefinition = appSchema.getDefinition(tableDefinitionName);
    const { visualization, targetAnnotation, namespace } = analyzeViewAnnotation(
        templateAnnotation,
        page.getUIAnnotations(),
        app.getAVT(),
        undefined,
        Visualization.LineItem,
        app.logger
    );
    if (visualization) {
        const annotationTerm = visualization.split('.')[1];
        schemaIdForColumns = `${DefinitionName.LineItems}OfSPV::${prepareRef(annotationTerm)}`;
        const spvTable = appSchema.cloneDefinition(tableDefinitionName, `${tableDefinitionName}SPV`);

        appSchema.setPropertyRef(
            spvTable,
            ['properties', 'toolBar'],
            `${DefinitionName.ToolBar}<${schemaIdForColumns}>`
        );

        // Switch from generic column to specific definition
        // schema.setProperty(spvTable, ['properties', 'columns'], {});
        appSchema.setProperty(spvTable, [SchemaTag.annotationPath], targetAnnotation);

        appSchema.setPropertyRef(spvTable, ['properties', 'columns'], schemaIdForColumns);
        appSchema.setDefinitionRef(tableDefinition, `${tableDefinitionName}SPV`);

        appSchema.removeProperty(spvTable, SchemaTag.isViewNode);
        appSchema.removeProperty(tableDefinition, 'properties');
        appSchema.setProperty(tableDefinition, [SchemaTag.annotationPath], `/${namespace}/@${templateAnnotation}`);
        const lineItemAnnotation = page.getUIAnnotations()[annotationTerm] as AnnotationTerm<LineItem>;
        if (!lineItemAnnotation) {
            log(app.logger, {
                severity: LogSeverity.Error,
                message: i18next.t('NOTARGET', { target: annotationTerm })
            });
        }
        const dataForLineItem: LineItemDataForSchema = {
            isObjectPage: false,
            appSchema: appSchema.get(),
            lineItemAnnotation,
            entityType: page.entity.type,
            oDataServiceAVT: app.getAVT(),
            lineItemId: schemaIdForColumns
        };
        addLineItemsTypeToSchema(dataForLineItem);
        const annotationTermQualifier = annotationTerm.split('#')?.[1];
        const sectionIdInManifest = annotationTermQualifier
            ? `@${UIAnnotationTerms.LineItem}#${annotationTermQualifier}`
            : `@${UIAnnotationTerms.LineItem}`;
        addCustomColumnDefinition(
            appSchema.get(),
            page.target,
            app.logger,
            undefined,
            schemaIdForColumns,
            sectionIdInManifest
        );
        addFragmentEnumForAnchor(appSchema.get(), schemaIdForColumns, page.target, undefined, sectionIdInManifest);

        // Table toolbar actions with custom actions
        schemaIdForActions = `${DefinitionName.Actions}<${schemaIdForColumns}>`;
        const customColumnDefinitionName = getCustomExtensionDefinitionName(
            appSchema.get(),
            schemaIdForColumns,
            DefinitionName.CustomTableAction
        );

        const schemaAdjustmentParameters: SchemaAdjustmentParameters = {
            logger: app.logger,
            appSchema: appSchema.get(),
            v4Page: page.target,
            tableDefinitionKey: `${tableDefinitionName}SPV`,
            facetDefinitionKey: schemaIdForColumns,
            dataForLineItem,
            entityType: page.entity.type,
            sectionActionsDefinitionKey: schemaIdForActions,
            scopedCustomActionDefinitionKey: getDefinitionKey(customColumnDefinitionName),
            customActionDefinitionName: DefinitionName.CustomTableAction,
            sectionIdInManifest
        };
        applyLRSchemaAdjustments(schemaAdjustmentParameters);
    } else {
        appSchema.setPropertyRef(tableDefinition, ['properties', 'toolBar'], `${DefinitionName.ToolBarLR}`);
        appSchema.setPropertyRef(tableDefinition, ['properties', 'columns'], `${DefinitionName.LineItems}`);
        // Switch from generic column to specific definition
        const lineItemAnnotation = page.getUIAnnotations()?.LineItem;
        if (!lineItemAnnotation && !page.target.options?.settings?.views?.paths) {
            log(app.logger, {
                severity: LogSeverity.Error,
                message: i18next.t('NOLINEITEMS')
            });
        }
        const dataForLineItem: LineItemDataForSchema = {
            isObjectPage: false,
            appSchema: appSchema.get(),
            lineItemAnnotation,
            entityType: page.entity.type,
            oDataServiceAVT: app.getAVT(),
            lineItemId: DefinitionName.LineItems
        };
        addLineItemsTypeToSchema(dataForLineItem);
        addCustomColumnDefinition(appSchema.get(), page.target, app.logger);
        addFragmentEnumForAnchor(appSchema.get(), DefinitionName.LineItems, page.target);

        schemaIdForActions = `${DefinitionName.Actions}<${prepareRef(schemaIdForColumns)}>`;

        const schemaAdjustmentParameters: SchemaAdjustmentParameters = {
            logger: app.logger,
            appSchema: appSchema.get(),
            v4Page: page.target,
            tableDefinitionKey: tableDefinitionName,
            facetDefinitionKey: schemaIdForColumns,
            dataForLineItem,
            entityType: page.entity.type,
            customActionDefinitionName: DefinitionName.CustomTableAction,
            sectionActionsDefinitionKey: schemaIdForActions
        };
        applyLRSchemaAdjustments(schemaAdjustmentParameters);

        if (lineItemAnnotation && !page.target.options?.settings?.views?.paths) {
            tableDefinition[SchemaTag.annotationPath] = createAnnotationPath(
                page.entity.type.fullyQualifiedName,
                lineItemAnnotation.term,
                lineItemAnnotation.qualifier
            );
        }
    }
    // Add "manifestPath" for table properties
    addManifestPathsToPropertiesLR(appSchema.get(), tableDefinitionName, tableDefinition, {
        pageName: page.target.id,
        manifest: app.getManifest(),
        targetAnnotation
    });
    // Add "manifestPath" for table columns and actions
    const customExtensionDefinitionNames = [schemaIdForColumns, schemaIdForActions];
    customExtensionDefinitionNames.forEach((definitionName) => {
        addManifestPathsToDefinitionPropertiesLR(appSchema.get(), page.target.id, definitionName, app.getManifest());
    });
}

/**
 * Add list report views to the app-specific schema.
 *
 * @param settings - general settings (App, Page, AppSchema, Logger)
 * @param tableDefinitionName - The name of the table definition in the schema
 */
function addLRViews(
    settings: GeneralSettings,
    tableDefinitionName: DefinitionName.Table | DefinitionName.ALPTableView
) {
    const { appSchema, app, page } = settings;
    const viewsPaths = page.config.views.paths;
    const tableDefinition = appSchema.getDefinition(tableDefinitionName);
    tableDefinition.properties = {
        annotationPath: tableDefinition.properties.annotationPath,
        initialLoad: tableDefinition.properties.initialLoad,
        views: tableDefinition.properties.views
    };
    const viewsDefinition = appSchema.getDefinition(DefinitionName.MultiTableModeV4);
    for (const view of viewsPaths) {
        if (!view[SchemaTag.key]) {
            continue;
        }
        let navPropName: string = undefined;
        const targetEntityType = getTargetEntityType(page.entity.set, view, page, app);
        const uiAnnotations = targetEntityType?.annotations.UI;
        const { visualization, targetAnnotation, namespace, title } = analyzeViewAnnotation(
            view?.[SchemaTag.annotationPath],
            uiAnnotations,
            app.getAVT(),
            view[SchemaTag.key],
            undefined,
            app.logger
        );
        if (view['entitySet']) {
            navPropName = page.entity.type.navigationProperties.find((np) => {
                return np.targetTypeName === namespace;
            })?.name;
        }
        const viewKey = prepareRef(view[SchemaTag.key]);
        const commonInputParameters: ViewsParameters = {
            viewKey,
            appSchema: appSchema.get(),
            targetAnnotation,
            navPropName,
            targetEntityType,
            title,
            entitySet: view['entitySet']
        };
        addLRViewParts(
            visualization,
            viewsDefinition,
            commonInputParameters,
            { serviceAVT: app.getAVT(), entityType: targetEntityType, logger: app.logger },
            page,
            app,
            uiAnnotations,
            view
        );
        addTagsToView(viewsDefinition, viewKey, namespace, view);
    }
}

export class TableAndViews extends BaseConstruct {
    /**
     * Initializes the addition of table and views to the schema.
     */
    init() {
        this.addTableAndViews();
    }

    /**
     * Adds table and views to the schema.
     */
    private addTableAndViews() {
        const tableDefinitionName = alignSchemaWithTemplateType(this.appSchema.get(), this.page.template.type);
        const config = this.page.config;

        if (this.page.template.type === TemplateType.ListReportObjectPageV4) {
            this.appSchema.hide(this.appSchema.getRootProperty([PropertyName.chart]));

            adaptTableDefinition(this.getSettings(), config.defaultAnnotation, tableDefinitionName);

            if (!config.views) {
                this.appSchema.setProperty(DefinitionName.MultiTableModeV4, ['properties'], {});
            } else if (config.views.paths) {
                this.appSchema.cleanup(['LineItems', 'ToolBar<LineItems>', 'Actions<LineItems>']);
                addLRViews(this.getSettings(), tableDefinitionName);
            }
        } else if (config.isALP) {
            const generateParameters = {
                logger: this.logger,
                entityType: this.page.getEntityType(),
                serviceAVT: this.app.getAVT()
            } as GenerateAppSchemaParameters;

            addALPViews(
                this.appSchema.get(),
                config.views?.paths,
                generateParameters,
                config.defaultAnnotation,
                this.page.target,
                tableDefinitionName
            );
            addFragmentEnumForAnchor(this.appSchema.get(), DefinitionName.LineItems, this.page.target);
        }
    }
}

/**
 * Enhances the List Report schema with manifest paths for definition and properties.
 *
 * This function extends the app schema (`appSchema`) by adding manifestPath to definition and properties on the List Report.
 *
 * @param {Definition} appSchema - The application schema object representing the List Report structure.
 * @param {string} pageId - Identifier of the page.
 * @param {string} definitionName - Identifier of the corresponding definition.
 * @param {Manifest} manifest - The application manifest.
 * @param {string} targetAnnotation - Target annotation.
 * @param {string} entitySet - Entity set.
 */
export function addManifestPathsToDefinitionPropertiesLR(
    appSchema: Definition,
    pageId: string,
    definitionName: string,
    manifest: Manifest,
    targetAnnotation?: string,
    entitySet?: string
): void {
    const matchingDefinition = appSchema.definitions[definitionName] as Definition;
    for (const key in matchingDefinition?.properties ?? {}) {
        const property = matchingDefinition.properties[key] as Definition;
        addManifestPathsToPropertiesLR(
            appSchema,
            undefined,
            property,
            {
                pageName: pageId,
                columnKey: key,
                manifest,
                targetAnnotation,
                viewConfig: {
                    entitySet
                }
            },
            true
        );
    }
}
