import type {
    ConvertedMetadata,
    EntitySet,
    EntityType,
    BaseNavigationProperty,
    AnnotationTerm
} from '@sap-ux/vocabularies-types';
import type { LineItem } from '@sap-ux/vocabularies-types/vocabularies/UI';
import type { XMLElement } from '@xml-tools/ast';
import type { SchemaDefinition } from '@sap/ux-specification-types';
import { UIVOCABULARY, DefinitionName } from '@sap/ux-specification-types';
import type { PageConnection } from '../../types';
import { addSelectionFields, analyzeViewAnnotation } from '../list-report/listReport';
import { findAlias, getAnnotationPathUsingFullyQualifiedName } from '../../../common';
import { getAttribute } from './utils';
import { appendLineItemsToSchema } from '../../utils/utils';
import type { LineItemDataForSchema } from '../../utils/utils';

export interface HandlerParams {
    serviceAVT: ConvertedMetadata;
    node: XMLElement;
    // Current parsing context schema
    schema: SchemaDefinition;
    // Full schema
    rootSchema: SchemaDefinition;
    connectionContext: PageConnection;
}

interface EntityTypeResolution {
    entityType: EntityType;
    metaPath?: string;
    qualifier?: string;
    annotationKey?: string;
}

interface MetaPathResolution {
    term?: string;
    path?: string;
}

type MacrosHandler = (params: HandlerParams) => void;

interface AnnotationPathData {
    term: AnnotationTerm<LineItem>;
    annotationPath?: string;
}

/**
 * Method resolves passed "metaPath" property from XML node.
 *
 * @param {string} metaPath "metaPath" property from XML node.
 * @returns {MetaPathResolution} Meta path resolution.
 */
function resolveMetaPath(metaPath: string): MetaPathResolution {
    const metaPathParts = metaPath.split('/');
    const pathParts: string[] = [];
    let term: string | undefined;
    for (const metaPathPart of metaPathParts) {
        if (metaPathPart) {
            if (metaPathPart.startsWith('@')) {
                term = metaPathPart;
                break;
            }
            pathParts.push(metaPathPart);
        }
    }
    if (pathParts.length) {
        return {
            path: pathParts.join('/'),
            term
        };
    }
    return { term: metaPath };
}

/**
 * Method returns entity type for passed macros annotation handler params.
 *
 * @param {HandlerParams} params Macros annotation handler params containing serviceAvt and connection context information.
 * @returns {EntityType | undefined} EntityType for passed connection.
 */
function getEntityTypeResolution(params: HandlerParams): EntityTypeResolution | undefined {
    const { node, serviceAVT, connectionContext } = params;
    const contextPath = getAttribute(node, 'contextPath') || connectionContext.contextPath;
    let metaPath = getAttribute(node, 'metaPath');
    const entitySet = connectionContext.entitySet;
    const isAbsoluteMetaPath = metaPath?.startsWith('/');
    if (!contextPath && !entitySet && !isAbsoluteMetaPath) {
        return undefined;
    }
    let path = contextPath || `/${entitySet}`;
    if (metaPath) {
        const metaPathResolution = resolveMetaPath(metaPath);
        if (metaPathResolution.path) {
            path = isAbsoluteMetaPath ? metaPathResolution.path : `${path}/${metaPathResolution.path}`;
            metaPath = metaPathResolution.term;
        }
    }
    const resolvedContextPath = serviceAVT?.resolvePath<EntitySet | EntityType | BaseNavigationProperty>(path);
    let entityType: EntityType | undefined;
    switch (resolvedContextPath?.target?.['_type']) {
        case 'EntitySet': {
            entityType = resolvedContextPath.target.entityType;
            break;
        }
        case 'NavigationProperty': {
            entityType = resolvedContextPath.target.targetType;
            break;
        }
        case 'EntityType': {
            entityType = resolvedContextPath.target;
            break;
        }
    }
    // Resolve qualifier
    let qualifier: string | undefined;
    const qualiferParts = metaPath.split('#');
    if (qualiferParts.length) {
        qualifier = qualiferParts[1];
    }
    // Annotation key in "vocabularies" annotations
    let annotationKey: string | undefined = undefined;
    if (metaPath) {
        const keyParts = metaPath.split('.');
        if (keyParts.length) {
            annotationKey = keyParts[keyParts.length - 1];
        }
    }
    return entityType
        ? {
              entityType,
              metaPath,
              qualifier,
              annotationKey
          }
        : undefined;
}

/**
 * Method applies annotation path for passed XML node's schema.
 *
 * @param {HandlerParams} schema Schema to update with "annotationPath".
 * @param {EntityTypeResolution} [entityTypeResolution] Entity type resolution object.
 */
function applyAnnotationPath(schema: SchemaDefinition, entityTypeResolution?: EntityTypeResolution): void {
    if (entityTypeResolution?.metaPath) {
        const { entityType, metaPath } = entityTypeResolution;
        schema.annotationPath = `/${entityType.fullyQualifiedName}/${metaPath}`;
    }
}

/**
 * Method returns data for table annotation line items for passed entity type resolution.
 *
 * @param {EntityTypeResolution} entityTypeResolution Entity type resolution object.
 * @param {ConvertedMetadata} serviceAVT Combined service metadata, as returned by annotation vocabularies tools.
 * @param {ConvertedMetadata} alias Annotation alias.
 * @returns {AnnotationPathData | undefined} Table annotation line items.
 */
function getDirectAnnotationPath(
    entityTypeResolution: EntityTypeResolution,
    serviceAVT: ConvertedMetadata,
    alias: string
): AnnotationPathData | undefined {
    const { metaPath, entityType } = entityTypeResolution;
    let term: AnnotationTerm<LineItem> | undefined;
    let annotationPath: string | undefined;
    if (entityType && metaPath) {
        const annotation = analyzeViewAnnotation(metaPath, entityType?.annotations?.[alias], serviceAVT);
        if (annotation.visualization) {
            const annotationTerm = annotation.visualization.split('.')[1];
            term = entityType?.annotations?.[alias]?.[annotationTerm];
            if (term?.fullyQualifiedName) {
                annotationPath = getAnnotationPathUsingFullyQualifiedName(entityType, term.fullyQualifiedName);
            }
        }
    }
    if (term) {
        return {
            term,
            annotationPath
        };
    }

    return undefined;
}

// Handlers map for macros controls
export const macrosHandlers: { [key: string]: MacrosHandler } = {
    'sap.fe.macros.Chart': (params: HandlerParams) => {
        const { schema, serviceAVT } = params;
        const entityTypeResolution = getEntityTypeResolution(params);
        applyAnnotationPath(schema, entityTypeResolution);
        if (schema.annotationPath) {
            const alias = findAlias(UIVOCABULARY, serviceAVT);
            const annotationData = getDirectAnnotationPath(entityTypeResolution, serviceAVT, alias);
            if (annotationData?.annotationPath) {
                params.schema.annotationPath = annotationData.annotationPath;
            }
        }
    },
    'sap.fe.macros.FilterBar': (params: HandlerParams) => {
        const { schema, serviceAVT, rootSchema } = params;
        const entityTypeResolution = getEntityTypeResolution(params);
        // Handler selection fields
        const filterFieldsDefinition = schema.properties?.filterFields;
        if (typeof filterFieldsDefinition === 'object' && entityTypeResolution?.annotationKey) {
            if (!filterFieldsDefinition.properties) {
                filterFieldsDefinition.properties = {};
            }
            const alias = findAlias(UIVOCABULARY, serviceAVT);
            const selectionFieldAnnotation =
                alias && entityTypeResolution.entityType?.annotations?.[alias]?.[entityTypeResolution.annotationKey];
            addSelectionFields(
                entityTypeResolution.entityType,
                rootSchema,
                selectionFieldAnnotation,
                filterFieldsDefinition,
                entityTypeResolution.qualifier
            );
        }
    },
    'sap.fe.macros.Table': (params: HandlerParams) => {
        const { schema, serviceAVT, rootSchema } = params;
        const entityTypeResolution = getEntityTypeResolution(params);
        const colDefinition = schema.properties.columns;
        const actionDefinition = schema.properties.actions;
        if (typeof colDefinition === 'object' && typeof actionDefinition === 'object' && entityTypeResolution) {
            if (!colDefinition.properties) {
                colDefinition.properties = {};
            }
            if (!actionDefinition.properties) {
                actionDefinition.properties = {};
            }
            const alias = findAlias(UIVOCABULARY, serviceAVT);
            applyAnnotationPath(schema, entityTypeResolution);

            if (schema.annotationPath) {
                const annotationData = getDirectAnnotationPath(entityTypeResolution, serviceAVT, alias);
                if (annotationData?.annotationPath) {
                    schema.annotationPath = annotationData.annotationPath;
                }
                const dataForLineItem: LineItemDataForSchema = {
                    isObjectPage: false,
                    appSchema: rootSchema,
                    lineItemAnnotation: annotationData.term,
                    entityType: entityTypeResolution.entityType,
                    oDataServiceAVT: serviceAVT,
                    lineItemId: DefinitionName.LineItems,
                    isMacro: true
                };
                appendLineItemsToSchema(dataForLineItem, actionDefinition, schema.annotationPath, colDefinition);
            }
        }
    },
    'sap.fe.macros.richtexteditor.ButtonGroup': (params: HandlerParams) => {
        const { node, schema } = params;
        const customToolBarPriority = getAttribute(node, 'customToolbarPriority');
        if (customToolBarPriority !== undefined) {
            // Set propertyIndex for UI ordering based on customToolbarPriority attribute
            schema.propertyIndex = Number(customToolBarPriority);
        }
    }
};
